    await p.locator(`#seguimiento-pagar-tarjeta-reparacion-${L}`).waitFor({ timeout: 20000 }).catch(() => {});
    const botonBizum = await texto(p, `#seguimiento-pagar-tarjeta-reparacion-${L}`);
