  const AJUSTES = { id: 1, activa: false, escala: null, dias_max: null, tipo_arras: null, al_vencer: null, texto_condiciones: null, condiciones_revisadas: false };
  const S = (n) => `0e000000-0000-4000-8000-0000000008b${n}`;
